async function supplierImage(request,u){
 const width=Number(u.pathname.split('/')[2]);if(![480,960].includes(width))return new Response('Invalid image size',{status:400});
 let source;try{source=new URL(u.searchParams.get('url'));}catch{return new Response('Invalid image',{status:400});}
 if(source.protocol!=='https:'||!/(^|\.)cjdropshipping\.com$|(^|\.)cjstatic\.com$|(^|\.)aliyuncs\.com$/.test(source.hostname)||source.username||source.password||source.port)return new Response('Image host not allowed',{status:400});
 source.searchParams.set('x-oss-process',`image/resize,w_${width}/quality,q_80/format,webp`);const key=new Request(SITE+'/cj-media/'+width+'/?url='+encodeURIComponent(source.href)),cache=globalThis.caches?.default;
 const hit=cache?await cache.match(key):null;if(hit)return request.method==='HEAD'?new Response(null,hit):hit;
 const upstream=await fetch(source,{redirect:'manual',signal:AbortSignal.timeout(15000)});if(!upstream.ok||!/^image\/(?:webp|png|jpe?g|gif|avif)(?:;|$)/i.test(upstream.headers.get('content-type')||''))return new Response('Supplier image unavailable',{status:502,headers:{'Cache-Control':'no-store'}});
 const reader=upstream.body.getReader(),chunks=[];let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>8_000_000){await reader.cancel();return new Response('Image exceeds limit',{status:413});}chunks.push(value);}
 const body=new Uint8Array(size);let offset=0;for(const part of chunks){body.set(part,offset);offset+=part.length;}
 const response=new Response(body,{headers:{'Content-Type':upstream.headers.get('content-type'),'Content-Length':String(size),'Cache-Control':'public,max-age=86400,s-maxage=604800','X-Content-Type-Options':'nosniff','X-Sasta-Image':'supplier-cache-v1','Content-Security-Policy':"default-src 'none'; sandbox"}});if(cache)await cache.put(key,response.clone());return request.method==='HEAD'?new Response(null,response):response;
}
